import { defineConfig } from "astro/config";
import react from "@astrojs/react";

export default defineConfig({ integrations: [react()] });

{
  "name": "memberstack-astro-starter",
  "private": true,
  "type": "module",
  "scripts": {
    "dev": "astro dev",
    "build": "astro build"
  },
  "dependencies": {
    "@astrojs/react": "^4.0.0",
    "@memberstack/dom": "^2.0.13",
    "astro": "^5.0.0",
    "react": "^19.0.0",
    "react-dom": "^19.0.0"
  }
}

import { useEffect, useState } from "react";
import { memberstack } from "./memberstack";
import { useRequireMember } from "./useMember";

export default function AccountForm() {
  const { member, status, error, refresh } = useRequireMember();
  const [first, setFirst] = useState("");
  const [last, setLast] = useState("");
  const [saved, setSaved] = useState(false);
  const [saveError, setSaveError] = useState("");
  const [busy, setBusy] = useState(false);

  // Seed the form once the member arrives. Without the guard this would clobber
  // whatever the person is typing on every re-render.
  useEffect(() => {
    if (!member) return;
    setFirst(member.customFields?.["first-name"] ?? "");
    setLast(member.customFields?.["last-name"] ?? "");
  }, [member]);

  if (error) {
    return <p className="notice">Could not reach Memberstack: {error}</p>;
  }
  if (status !== "in" || !member) return null;

  const plans = member.planConnections?.filter((plan) => plan.active) ?? [];

  return (
    <div className="auth">
      <span className="eyebrow">Account</span>
      <h1>Your details</h1>
      <p className="sub">
        This reads and writes the same custom fields your signup form collected.
      </p>

      <div className="card">
        {saveError && <p className="err">{saveError}</p>}
        {saved && <p className="ok">Saved.</p>}

        <form
          onSubmit={async (event) => {
            event.preventDefault();
            setBusy(true);
            setSaved(false);
            setSaveError("");
            try {
              // updateMember takes the whole customFields object. Keys missing
              // from your dashboard are dropped silently, same as at signup.
              await memberstack.updateMember({
                customFields: { "first-name": first, "last-name": last },
              });
              await refresh();
              setSaved(true);
            } catch (err) {
              setSaveError(err?.message || "Could not save those changes.");
            }
            setBusy(false);
          }}
        >
          <div className="row">
            <div>
              <label htmlFor="first">First name</label>
              <input
                id="first"
                value={first}
                onChange={(e) => setFirst(e.target.value)}
              />
            </div>
            <div>
              <label htmlFor="last">Last name</label>
              <input
                id="last"
                value={last}
                onChange={(e) => setLast(e.target.value)}
              />
            </div>
          </div>

          <button type="submit" className="btn btn-primary" disabled={busy}>
            {busy ? "Saving…" : "Save changes"}
          </button>
        </form>
      </div>

      <div className="card" style={{ marginTop: 16 }}>
        <h2>Membership</h2>
        <dl className="dl" style={{ marginTop: 14 }}>
          <div>
            <dt>Email</dt>
            <dd>{member.auth?.email}</dd>
          </div>
          <div>
            <dt>Member ID</dt>
            <dd>{member.id}</dd>
          </div>
          <div>
            <dt>Plan</dt>
            <dd>
              {plans.length
                ? plans.map((plan) => plan.planId).join(", ")
                : "None"}
            </dd>
          </div>
        </dl>

        {!plans.length && (
          <p className="hint">
            No plan is needed — this site gates on being signed in. To gate on a
            plan instead, pass <code>plans</code> at signup or call{" "}
            <code>addPlan()</code>.
          </p>
        )}
      </div>
    </div>
  );
}

import { memberstack } from "./memberstack";

/**
 * Google sign-in.
 *
 * This works the moment you run the starter — Google is enabled on every new
 * Memberstack app by default, using Memberstack's own OAuth credentials, so
 * there is no Google Cloud project to create first. Two thirds of live
 * Memberstack sites offer it, which is why it is here rather than the README.
 *
 * `allowSignup: true` means one button covers both cases: an existing member
 * signs in, a new one gets an account.
 *
 * WHY onSignedIn EXISTS. loginWithProvider opens a POPUP, it does not redirect
 * this page. The popup closes, the SDK stores the session, and the promise
 * below resolves — in a document that is still sitting on the login form. So
 * awaiting it is only half the job: without this callback the member is signed
 * in and the screen never moves, which reads as "the button did nothing" and
 * invites a second click. The email/password handler does the same two things.
 */
export default function GoogleButton({ label, onError, onSignedIn }) {
  return (
    <button
      type="button"
      className="btn btn-google"
      onClick={async () => {
        try {
          await memberstack.loginWithProvider({
            provider: "google",
            allowSignup: true,
          });
          // The popup is gone and the session exists, but this page has not
          // moved. That is what onSignedIn is for.
          await onSignedIn?.();
        } catch (err) {
          // A closed popup rejects here too, so this is not always an error
          // worth shouting about — but silence would leave the button looking
          // broken.
          onError?.(err?.message || "Google sign-in did not complete.");
        }
      }}
    >
      <svg viewBox="0 0 18 18" aria-hidden="true" width="18" height="18">
        <path
          fill="#4285F4"
          d="M17.64 9.2c0-.64-.06-1.25-.16-1.84H9v3.48h4.84a4.14 4.14 0 0 1-1.8 2.72v2.26h2.92c1.7-1.57 2.68-3.88 2.68-6.62z"
        />
        <path
          fill="#34A853"
          d="M9 18c2.43 0 4.47-.8 5.96-2.18l-2.92-2.26c-.8.54-1.84.86-3.04.86-2.34 0-4.32-1.58-5.03-3.7H.96v2.34A9 9 0 0 0 9 18z"
        />
        <path
          fill="#FBBC05"
          d="M3.97 10.72a5.4 5.4 0 0 1 0-3.44V4.94H.96a9 9 0 0 0 0 8.12l3.01-2.34z"
        />
        <path
          fill="#EA4335"
          d="M9 3.58c1.32 0 2.5.45 3.44 1.35l2.58-2.58C13.46.9 11.42 0 9 0A9 9 0 0 0 .96 4.94l3.01 2.34C4.68 5.16 6.66 3.58 9 3.58z"
        />
      </svg>
      {label}
    </button>
  );
}

import { useState } from "react";
import GoogleButton from "./GoogleButton";
import { memberstack } from "./memberstack";

export default function LoginForm() {
  const [error, setError] = useState("");
  const [busy, setBusy] = useState(false);
  const [email, setEmail] = useState("");
  // "password" | "code-sent"
  const [mode, setMode] = useState("password");

  /**
   * Passwordless login, in two steps: Memberstack emails a one-time code, the
   * member types it back in. Adoption of this roughly triples between small
   * apps and large ones, which is why it is wired up rather than left as an
   * exercise.
   *
   * It is OFF on a new app. Turn it on in the dashboard under Authentication,
   * or the request below comes back with an error saying so.
   */
  const requestCode = async () => {
    setError("");
    if (!email) {
      setError("Enter your email first, then request a code.");
      return;
    }
    setBusy(true);
    try {
      await memberstack.sendMemberLoginPasswordlessEmail({ email });
      setMode("code-sent");
    } catch (err) {
      setError(
        err?.message ||
          "Could not send a code. Passwordless may be off for this app."
      );
    }
    setBusy(false);
  };

  const submitCode = async (event) => {
    event.preventDefault();
    setError("");
    setBusy(true);
    try {
      await memberstack.loginMemberPasswordless({
        email,
        passwordlessToken: new FormData(event.currentTarget).get("code"),
      });
      window.location.href = "/members";
    } catch (err) {
      setError(
        err?.message || "That code did not work. Try requesting a new one."
      );
      setBusy(false);
    }
  };

  const submitPassword = async (event) => {
    event.preventDefault();
    setError("");
    setBusy(true);
    try {
      await memberstack.loginMemberEmailPassword({
        email,
        password: new FormData(event.currentTarget).get("password"),
      });
      window.location.href = "/members";
    } catch (err) {
      setError(err?.message || "That email and password did not match.");
      setBusy(false);
    }
  };

  return (
    <div className="auth">
      <div className="card">
        <h1>Welcome back</h1>
        <p className="sub">Log in to reach your library.</p>

        {error && <p className="err">{error}</p>}

        {mode === "code-sent" ? (
          <>
            <p className="ok">We emailed a one-time code to {email}.</p>
            <form onSubmit={submitCode}>
              <label htmlFor="code">Your code</label>
              <input
                id="code"
                name="code"
                inputMode="numeric"
                autoFocus
                required
              />
              <button type="submit" className="btn btn-primary" disabled={busy}>
                {busy ? "Checking…" : "Log in"}
              </button>
            </form>
            <p className="alt">
              <button
                type="button"
                className="linkish"
                onClick={() => {
                  setMode("password");
                  setError("");
                }}
              >
                Use a password instead
              </button>
            </p>
          </>
        ) : (
          <>
            <GoogleButton
          label="Continue with Google"
          onError={setError}
          onSignedIn={() => {
            // A full load, so every island on /members reads the new session.
            window.location.href = "/members";
          }}
        />

            <div className="or">or</div>

            <form onSubmit={submitPassword}>
              <label htmlFor="email">Email</label>
              <input
                id="email"
                name="email"
                type="email"
                autoComplete="email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                required
              />

              <label htmlFor="password">Password</label>
              <input
                id="password"
                name="password"
                type="password"
                autoComplete="current-password"
                required
              />

              <button type="submit" className="btn btn-primary" disabled={busy}>
                {busy ? "Logging in…" : "Log in"}
              </button>
            </form>

            <p className="alt">
              <button
                type="button"
                className="linkish"
                onClick={requestCode}
                disabled={busy}
              >
                Email me a code instead
              </button>
            </p>
          </>
        )}

        <p className="alt">
          New here? <a href="/signup">Create an account</a>
        </p>
      </div>
    </div>
  );
}

import { site } from "../site.config";
import { useRequireMember } from "./useMember";

export default function MembersArea() {
  const { member, status, error } = useRequireMember();

  // A bad public key surfaces here rather than as a blank page that never
  // resolves. This is the difference between "five minutes" and "an afternoon"
  // when the key is wrong.
  if (error) {
    return (
      <p className="notice">
        Could not reach Memberstack: {error}
        <br />
        Check <code>PUBLIC_MEMBERSTACK_PUBLIC_KEY</code> in{" "}
        <code>.env.local</code>.
      </p>
    );
  }

  // "loading" and "out" both render nothing: one is about to resolve, the other
  // is about to redirect. Rendering the page for either is what causes gated
  // content to flash before it disappears.
  if (status !== "in" || !member) return null;

  const firstName = member.customFields?.["first-name"];

  return (
    <>
      <span className="eyebrow">Members</span>
      <h1>{firstName ? `Welcome back, ${firstName}.` : "Welcome back."}</h1>
      <p className="sub">
        Everything below is behind the login. Signed out visitors get sent to
        the login page.
      </p>

      <div className="grid">
        {site.resources.map((resource) => (
          <article className="card" key={resource.title}>
            <span className="kind">{resource.kind}</span>
            <h2>{resource.title}</h2>
            <p>{resource.body}</p>
          </article>
        ))}
      </div>
    </>
  );
}

import { site } from "../site.config";
import { memberstack } from "./memberstack";
import { useMember } from "./useMember";

/**
 * The nav is an island because it changes with the session.
 *
 * `pathname` comes in as a prop from the .astro page rather than being read
 * here: the page already knows it at build time, so there is no reason to ask
 * the browser.
 */
export default function Nav({ pathname }) {
  // Astro's build emits directory-style URLs (/members/), while dev serves
  // /members. Normalising here keeps the active state working in both, instead
  // of silently doing nothing in production only.
  const path = pathname.replace(/\/+$/, "") || "/";
  const { member, status, refresh } = useMember();

  return (
    <nav className="nav-links">
      {/* Rendering nothing while the session resolves keeps the nav from
          flickering "Log in" at a member who is already signed in. */}
      {status === "loading" ? null : member ? (
        <>
          <a
            href="/members"
            className={path === "/members" ? "active" : undefined}
          >
            Members
          </a>
          <a
            href="/account"
            className={path === "/account" ? "active" : undefined}
          >
            Account
          </a>
          <button
            type="button"
            className="btn btn-ghost"
            onClick={async () => {
              await memberstack.logout();
              await refresh();
              // A full load, not a history push: every island on the next page
              // re-reads the session, which is how this starter stays in sync
              // without shared state.
              window.location.href = "/";
            }}
          >
            Log out
          </button>
        </>
      ) : (
        <>
          <a href="/login">Log in</a>
          <a href="/signup" className="btn btn-primary btn-sm">
            Sign up
          </a>
        </>
      )}
    </nav>
  );
}

import { useState } from "react";
import GoogleButton from "./GoogleButton";
import { memberstack } from "./memberstack";

export default function SignupForm() {
  const [error, setError] = useState("");
  const [busy, setBusy] = useState(false);

  return (
    <div className="auth">
      <div className="card">
        <h1>Create your account</h1>
        <p className="sub">Free, and takes about ten seconds.</p>

        {error && <p className="err">{error}</p>}

        <GoogleButton
          label="Continue with Google"
          onError={setError}
          onSignedIn={() => {
            // A full load, so every island on /members reads the new session.
            window.location.href = "/members";
          }}
        />

        <div className="or">or</div>

        <form
          onSubmit={async (event) => {
            event.preventDefault();
            setError("");
            setBusy(true);
            const form = new FormData(event.currentTarget);

            try {
              await memberstack.signupMemberEmailPassword({
                email: form.get("email"),
                password: form.get("password"),
                /**
                 * These two keys are not invented — every Memberstack app is
                 * created with `first-name` and `last-name` custom fields
                 * already defined, so they work with no dashboard setup.
                 *
                 * Note the kebab-case. Custom field keys are matched exactly,
                 * and a key that does not exist in your dashboard is dropped
                 * SILENTLY: no error, the value simply never arrives. If you
                 * add a field to this form, create it in the dashboard first
                 * (Members -> Custom fields) or you will be debugging a value
                 * that vanishes without a trace.
                 */
                customFields: {
                  "first-name": form.get("firstName"),
                  "last-name": form.get("lastName"),
                },
                /**
                 * To put every new member on a plan, pass it here:
                 *   plans: [{ planId: "pln_..." }]
                 * Members are created fine without one, which is why this
                 * starter gates on being signed in rather than on a plan.
                 */
              });
              // A full document load, not a history push. Astro is multi-page,
              // so this is what makes the nav on /members reflect the new
              // session — every island there reads it fresh.
              window.location.href = "/members";
            } catch (err) {
              // Signing up an address that already exists rejects here, which
              // is the single most common thing to hit while testing. Showing
              // it beats a form that looks like it did nothing.
              setError(err?.message || "Could not create that account.");
              setBusy(false);
            }
          }}
        >
          <div className="row">
            <div>
              <label htmlFor="firstName">First name</label>
              <input
                id="firstName"
                name="firstName"
                autoComplete="given-name"
                required
              />
            </div>
            <div>
              <label htmlFor="lastName">Last name</label>
              <input
                id="lastName"
                name="lastName"
                autoComplete="family-name"
                required
              />
            </div>
          </div>

          <label htmlFor="email">Email</label>
          <input
            id="email"
            name="email"
            type="email"
            autoComplete="email"
            required
          />

          <label htmlFor="password">Password</label>
          <input
            id="password"
            name="password"
            type="password"
            autoComplete="new-password"
            minLength={8}
            required
          />

          <button type="submit" className="btn btn-primary" disabled={busy}>
            {busy ? "Creating your account…" : "Create account"}
          </button>
        </form>

        <p className="alt">
          Already have an account? <a href="/login">Log in</a>
        </p>
      </div>
    </div>
  );
}

import memberstackDOM from "@memberstack/dom";

// Anything with this prefix is exposed to the browser by the build tool. A
// public key is designed to ship in front-end code, so this is the right place.
export const memberstack = memberstackDOM.init({
  publicKey: import.meta.env.PUBLIC_MEMBERSTACK_PUBLIC_KEY,
});

import { useCallback, useEffect, useState } from "react";
import { memberstack } from "./memberstack";

/**
 * The session, as three states rather than two.
 *
 *   "loading" - the first getCurrentMember() has not come back yet
 *   "in"      - there is a member
 *   "out"     - there is no member, or the lookup failed
 *
 * `member` alone cannot tell "signed out" apart from "we have not asked yet",
 * and treating those the same is what makes a gated page flash its contents
 * before redirecting.
 *
 * NOTE FOR ASTRO: unlike the React, Vue and Svelte starters, there is no shared
 * session here and that is deliberate. Astro is multi-page — every navigation
 * is a full document load, so the nav is rebuilt from scratch each time and
 * cannot go stale. The React starter needs a context provider to stop the nav
 * saying "Log in" after signup; that bug simply cannot happen here, so adding
 * cross-island state (nanostores or similar) would be a dependency solving a
 * problem this architecture does not have.
 *
 * The one thing to remember: after signing in or out, navigate with
 * `window.location` rather than pushing history, so every island re-reads the
 * session on the new document.
 */
export function useMember() {
  const [member, setMember] = useState(null);
  const [status, setStatus] = useState("loading");
  const [error, setError] = useState("");

  const refresh = useCallback(async () => {
    try {
      const { data } = await memberstack.getCurrentMember();
      setMember(data ?? null);
      setStatus(data ? "in" : "out");
      setError("");
    } catch (err) {
      // Almost always a bad public key. Without this branch the island renders
      // nothing forever and there is no clue on screen as to why.
      setMember(null);
      setStatus("out");
      setError(err?.message || "Could not reach Memberstack.");
    }
  }, []);

  useEffect(() => {
    refresh();
  }, [refresh]);

  return { member, status, error, refresh };
}

/**
 * Route protection, in one place.
 *
 * This gate runs in the browser, which is the right tool for showing and hiding
 * UI. Anything that must never reach a signed-out visitor has to be checked on
 * your server too, with @memberstack/admin. A client-side check is a UX
 * affordance, not a security boundary — and on a static Astro build the page
 * HTML is public regardless, so keep real secrets out of gated pages entirely.
 */
export function useRequireMember() {
  const session = useMember();

  useEffect(() => {
    // Not when the SDK itself failed — those islands show the error instead,
    // so the cause stays on screen. `replace` keeps the gated URL out of
    // history, so Back does not bounce the visitor through it again.
    if (session.status === "out" && !session.error) {
      window.location.replace("/login");
    }
  }, [session.status, session.error]);

  return session;
}

/**
 * Everything fictional about this starter lives here.
 *
 * Swapping the demo business for your own is meant to be one file. If you find
 * yourself editing a component to change a name, a headline, or a list item,
 * that content belongs in here instead.
 */

